package hu.boltseged.admin;
import hu.boltseged.account.*; import hu.boltseged.shipment.*; import org.junit.jupiter.api.Test; import org.springframework.data.domain.*; import java.math.*; import java.time.*; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.ArgumentMatchers.*; import static org.mockito.Mockito.*;
class AdminBillingCurrencyTest {
 private Shipment shipment(String currency,BigDecimal cost,BigDecimal price){Account account=new Account("A","a@example.com","hash","CUSTOMER");Shipment shipment=new Shipment(account,"key-"+currency,"P",LocalDate.of(2026,1,1),"{}","{}",List.of(new Shipment.PackageInput(BigDecimal.ONE,BigDecimal.ONE,BigDecimal.ONE,BigDecimal.ONE)));shipment.price(cost,price);shipment.complete("tracking","dhl",List.of("piece"),cost,currency);return shipment;}
 @Test void csvAndBillingRowUsePersistedShipmentCurrency(){ShipmentRepository repo=mock(ShipmentRepository.class);Shipment huf=shipment("HUF",new BigDecimal("8470"),new BigDecimal("9470"));when(repo.findAll(any(org.springframework.data.jpa.domain.Specification.class),any(Sort.class))).thenReturn(List.of(huf));when(repo.findAll(any(org.springframework.data.jpa.domain.Specification.class),any(Pageable.class))).thenReturn(new PageImpl<>(List.of(huf)));AdminBillingController controller=new AdminBillingController(repo,mock(AccountRepository.class));String csv=new String(controller.csv(null,null,null,null,null,null).getBody(),java.nio.charset.StandardCharsets.UTF_8);assertTrue(csv.contains(",9470,HUF,"));assertFalse(csv.contains(",EUR,"));assertEquals("HUF",controller.list(null,null,null,null,null,null,Pageable.unpaged()).getContent().getFirst().currency());}
 @Test void summaryKeepsCurrenciesSeparateAndCalculatesMarginPerCurrency(){ShipmentRepository repo=mock(ShipmentRepository.class);when(repo.summaryByCurrency(null,null,null,null)).thenReturn(List.of(new Object[]{1L,new BigDecimal("8470"),new BigDecimal("9470"),"HUF"},new Object[]{2L,new BigDecimal("50"),new BigDecimal("60"),"EUR"}));List<BillingSummaryController.Summary> summary=new BillingSummaryController(repo).summary(null,null,null,null);assertEquals(2,summary.size());assertEquals(new BigDecimal("1000"),summary.stream().filter(x->x.currency().equals("HUF")).findFirst().orElseThrow().totalMargin());assertEquals(new BigDecimal("10"),summary.stream().filter(x->x.currency().equals("EUR")).findFirst().orElseThrow().totalMargin());}
}
